'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {downloadReport,reportUsd} from '@/lib/report-export';
import {followUpStates,followUpBasis,followUpMoney,followUpStatusLabel,type FollowUpQueueScope,type FollowUpFilters} from '@/lib/balance-follow-up';

import {routedFollowUpQueueCsv as followUpQueueCsv,validateRoutedFollowUpQueue as validateFollowUpQueue,type RoutedFollowUpQueue as FollowUpQueue} from '@/lib/billing-follow-up';

type Props=FollowUpQueueScope&{disabled?:boolean;revision?:number;onOpen:(reservation:string)=>void};
export function BillingFollowUpQueue(props:Props){return <QueueWorkspace key={[props.actor,props.tenant,props.property].join('/')} {...props}/>}
function QueueWorkspace({actor,tenant,property,disabled=false,revision=0,onOpen}:Props){
 const [filters,setFilters]=useState<FollowUpFilters>({state:'open',schedule:'all'}),[refresh,setRefresh]=useState(0),[page,setPage]=useState(0),[response,setResponse]=useState<{key:string;value:FollowUpQueue|null;error:string}|null>(null);
 const key=JSON.stringify([actor,tenant,property,filters.state,filters.schedule,revision,refresh]),sequence=useRef(0);
 useEffect(()=>{let alive=true;const version=++sequence.current;void hotelRpc<unknown>('billing_follow_up_queue',{p_tenant:tenant,p_property:property,p_filters:filters}).then(value=>{validateFollowUpQueue(value,{actor,tenant,property},filters);if(alive&&sequence.current===version)setResponse({key,value,error:''})}).catch(()=>{if(alive&&sequence.current===version)setResponse({key,value:null,error:'The complete follow-up queue could not be verified. Refresh before using its rows or export.'})});return()=>{alive=false}},[actor,tenant,property,filters,key]);
 const loaded=response?.key===key,data=loaded?response.value:null,error=loaded?response.error:'',loading=!loaded,pageSize=50,index=Math.min(page,Math.max(0,Math.ceil((data?.rows.length??0)/pageSize)-1)),visible=data?.rows.slice(index*pageSize,(index+1)*pageSize)??[];
 return <section className="card pilot-balance-queue"><style>{'.pilot-balance-queue .follow-up-content{padding:0 24px 24px}.pilot-balance-queue .pilot-actions{flex-wrap:wrap}.pilot-balance-queue h3{font-size:16px;font-weight:600;margin:20px 0 8px}.pilot-balance-queue p,.pilot-balance-queue td{overflow-wrap:anywhere}.pilot-balance-queue .detail-grid{grid-template-columns:repeat(auto-fit,minmax(150px,1fr))}.pilot-balance-queue .pilot-table td{vertical-align:top}.pilot-balance-queue .pilot-table small{display:block}.pilot-balance-queue .pilot-actions .primary{font-size:14px}@media(max-width:600px){.pilot-balance-queue .follow-up-content{padding:0 16px 16px}}'}</style>
  <div className="section-top"><h2>Recorded balance follow-ups</h2><span className="count">{data?data.summary.row_count:'—'}</span></div><div className="follow-up-content">
  <p>This worklist includes recorded follow-ups only. Staff follow-up dates are internal work schedules, not payment due dates or receivables age.</p>
  <div className="pilot-grid"><label className="field">Follow-up state<select value={filters.state} disabled={disabled} onChange={e=>{setFilters({state:e.target.value as FollowUpFilters['state'],schedule:'all'});setPage(0)}}><option value="open">Open</option><option value="completed">Review completed</option><option value="stopped">Stopped</option><option value="all">All states</option></select></label><label className="field">Staff follow-up schedule<select value={filters.schedule} disabled={disabled||filters.state!=='open'} onChange={e=>{setFilters(current=>({...current,schedule:e.target.value as FollowUpFilters['schedule']}));setPage(0)}}><option value="all">All scheduled dates</option><option value="past">Past staff follow-up date</option><option value="today">Today</option><option value="future">Future</option></select></label></div>
  <div className="pilot-actions"><button className="secondary" disabled={disabled||loading} onClick={()=>setRefresh(n=>n+1)}>Refresh follow-up queue</button><button className="secondary" disabled={disabled||loading||!data} onClick={()=>{if(data)downloadReport('balance-follow-up-'+data.property_business_date,followUpQueueCsv(data))}}>Export follow-up CSV</button></div>
  {error&&<div className="pilot-error" role="alert">{error}</div>}{loading&&<output className="pilot-empty">Preparing the complete follow-up queue…</output>}
  {data&&<><p>{data.property.name} · {data.property.time_zone} · Property business date {data.property_business_date}</p><p className="muted">Prepared {new Intl.DateTimeFormat('en-US',{timeZone:data.property.time_zone,dateStyle:'medium',timeStyle:'long'}).format(new Date(data.generated_at))}. All counts and amounts below describe these selected rows.</p>
   <div className="detail-grid"><div>Open<b>{data.summary.open_count}</b></div><div>Past staff follow-up date<b>{data.summary.past_count}</b></div><div>Review completed<b>{data.summary.completed_count}</b></div><div>Stopped<b>{data.summary.stopped_count}</b></div></div>
   <h3>Known amounts in this selection</h3><p>{data.summary.amounts_complete?'All selected current balances are available.':data.summary.unavailable_count+' selected current balances are unavailable and excluded from these known subtotals.'} Refundable security funds are excluded.</p>
   <div className="detail-grid"><div>Known charges<b>{reportUsd(data.summary.known_charges_minor)}</b></div><div>Known recorded paid<b>{reportUsd(data.summary.known_recorded_paid_minor)}</b></div><div>Known guest balance<b>{reportUsd(data.summary.known_balance_minor)}</b></div><div>Known positive balances<b>{reportUsd(data.summary.known_positive_balances_minor)}</b></div><div>Known credits<b>{reportUsd(data.summary.known_credit_balances_minor)}</b></div></div>
   <p>{data.summary.positive_balance_count} positive · {data.summary.zero_balance_count} zero · {data.summary.credit_balance_count} credit · {data.summary.unavailable_count} unavailable. {data.summary.context_changed_count} balances or booking contexts changed; {data.summary.pricing_review_count} require pricing review.</p>
  </>}
  </div>
  {data&&<><div className="pilot-table-wrap"><table className="pilot-table"><caption>Recorded follow-ups in the selected staff schedule</caption><thead><tr><th scope="col">Reservation</th><th scope="col">Staff follow-up</th><th scope="col">Guest balance</th><th scope="col">Review notes</th><th scope="col">Action</th></tr></thead><tbody>{visible.map(row=><tr key={row.reservation.id}>
   <td><strong>{row.reservation.source_booking_id}</strong><small>{row.reservation.source} · {followUpStatusLabel(row.reservation)}</small></td>
   <td><strong>{followUpStates[row.head.state]}</strong><small>{row.head.state==='open'?'Staff follow-up date':'Last scheduled follow-up'}: {row.head.follow_up_on}</small>{row.follow_up_bucket==='past'?<small>Days past staff follow-up: {row.days_past_follow_up}</small>:row.follow_up_bucket!=='inactive'&&<small>{row.follow_up_bucket==='today'?'Scheduled today':'Scheduled for a future date'}</small>}</td>
   <td><strong>Current: {followUpMoney(row.current_balance.balance_minor)}</strong><small>{followUpBasis(row.current_balance)}</small><small>Transferred to company: {followUpMoney(row.current_balance.routed_charge_minor)}</small><small>Original balance: {followUpMoney(row.current_balance.original_balance_minor)}</small><p>Last reviewed: {followUpMoney(row.last_action.reviewed_balance.balance_minor)}<small>{followUpBasis(row.last_action.reviewed_balance)}</small></p></td>
   <td>{row.context_changed_since_recording&&<p>Balance or booking context changed since this action.</p>}{row.current_balance.flags.pricing_reconciliation_required&&<p>Pricing reconciliation required.</p>}{row.schedule_zone_changed&&<p>The property time zone changed; the scheduled civil date remains unchanged.</p>}{!row.context_changed_since_recording&&!row.current_balance.flags.pricing_reconciliation_required&&!row.schedule_zone_changed&&<p>No recorded context or zone change.</p>}</td>
   <td><button className="text-button" disabled={disabled} onClick={()=>onOpen(row.reservation.id)}>Review follow-up</button></td>
  </tr>)}</tbody></table></div><div className="follow-up-content">{data.rows.length===0?<p>No recorded follow-ups match these filters. To schedule a first follow-up, open a reservation’s Manage screen and choose Balance follow-up. Unscheduled accounts are not included here.</p>:<div className="pilot-actions"><button className="secondary" disabled={disabled||index===0} onClick={()=>setPage(n=>Math.max(0,n-1))}>Previous follow-ups</button><p>Showing {index*pageSize+1}–{Math.min((index+1)*pageSize,data.rows.length)} of {data.rows.length}. Export includes every selected row.</p><button className="secondary" disabled={disabled||(index+1)*pageSize>=data.rows.length} onClick={()=>setPage(n=>n+1)}>Next follow-ups</button></div>}</div></>}
 </section>;
}
